record.field:
{
    "type": "object",
    "properties": {
        "campaign_id": {
            "type": "integer",
            "description": "ID of the campaign whose activities should be sorted."
        }
    },
    "required": ["campaign_id"]
}

{
    "type": "object",
    "properties": {
        "module_name": {
            "type": "string",
            "description": "Name of the module to check if it's installed."
        }
    },
    "required": ["module_name"]
}

{
    "type": "object",
    "properties": {
        "activity_id": {
            "type": "integer",
            "description": "ID of the marketing.activity whose step should be removed."
        },
        "step_type": {
            "type": "string",
            "description": "Which part of the node to remove. Use 'delay' to remove only the waiting period and keep the step itself, 'trigger' to remove the interaction node, or the activity's own type (email, action, split, log_note, subscribe_to_list, structure) to remove the activity."
        },
        "cascade_delete": {
            "type": "boolean",
            "description": "Send false for every step except the root. True is only for deleting the root activity (trigger_type 'begin'), which removes the entire campaign workflow and requires the user's explicit confirmation first. Always send this explicitly."
        }
    },
    "required": ["activity_id", "step_type", "cascade_delete"]
}
